// biome-ignore lint/suspicious/noExplicitAny: the vectors are JSON
const vector = (name: string): any => JSON.parse(readFileSync(join(VECTOR_DIR, name), "utf8"));

/** Decodes bytes with a decoder in the given state; returns frames or the close code. */
function decode(hex: string, limit: number = LINK2_TCP_PAYLOAD, linked = true): { frames: Link2Frame[]; close: string | null; buffered: number } {
  const decoder = new Link2FrameDecoder();
  if (linked) decoder.ready(limit);
  try {
    return { frames: decoder.push(fromHex(hex)), close: null, buffered: decoder.buffered };
  } catch (error) {
    if (!(error instanceof LinkCloseError)) throw error;
    return { frames: [], close: error.code, buffered: decoder.buffered };
  }
}
const one = (hex: string, limit?: number, linked?: boolean): Link2Frame => {
  const { frames, close } = decode(hex, limit, linked);
  expect(close).toBeNull();
  expect(frames.length).toBe(1);
  return frames[0];
};
const jsonOf = (hex: string) => parseJsonPayload(one(hex));
const nothing: Holdings = { channelRequest: () => false, ownRequest: () => false, channel: () => false, inUse: () => false };
const clock = (start = 0) => {
  let t = start;
  return { now: () => t, advance: (ms: number) => (t += ms), set: (ms: number) => (t = ms) };
};

describe("vectors", () => {
  test("the files on disk are what the generator writes", () => {
    for (const [name, value] of Object.entries(buildVectors())) {
      expect(readFileSync(join(VECTOR_DIR, name), "utf8")).toBe(serialize(value));
    }
  });
});

describe("beacon (§2.2)", () => {
  const v = vector("beacon.json");
  test("bytes written by hand", () => {
    const bytes = encodeBeacon({ port: 8628, companion: FIXED.hub, name: "Studio Mac" });
    const expected = `504b4c42${"02"}${"00"}${"b421"}${toHex(new TextEncoder().encode(FIXED.hub))}${toHex(new TextEncoder().encode("Studio Mac"))}`.padEnd(128, "0");
    expect(toHex(bytes)).toBe(expected);
  });
  test("accepted", () => {
    for (const c of v.accepted) expect(decodeBeacon(fromHex(c.hex))).toEqual({ port: c.port, companion: c.companion, name: c.text });
  });
  test("refused", () => {
    for (const c of v.refused) expect(decodeBeacon(fromHex(c.hex))).toBeNull();
  });
  test("an encoder refuses port 0 and a bad id", () => {
    expect(() => encodeBeacon({ port: 0, companion: FIXED.hub, name: "" })).toThrow(LinkEncodeError);
    expect(() => encodeBeacon({ port: 1, companion: "XYZ", name: "" })).toThrow(LinkEncodeError);
  });
});

describe("preamble (§4.1)", () => {
  const v = vector("preamble.json");
  test("the device's preamble", () => {
    expect(v.device).toBe("504b4c4b02020000");
    expect(decodePreamble(fromHex(v.device))).toEqual({ highest: 2, lowest: 2, selected: 0 });
  });
  test("Hub's selection", () => {
    for (const c of v.selection) {
      const device = decodePreamble(fromHex(c.deviceHex));
      expect(device).not.toBeNull();
      expect(selectVersion(c.hub, device!)).toBe(c.selected);
      expect(toHex(encodePreamble({ ...c.hub, selected: c.selected }))).toBe(c.hubHex);
    }
    const byName = (name: string) => v.selection.find((c: { name: string }) => c.name.startsWith(name));
    expect(byName("a version-2 device").selected).toBe(2);
    expect(byName("a version-1 console").selected).toBe(0);
    expect(byName("a device with range 2 to 3").selected).toBe(2);
    expect(byName("a device with range 3 to 4").selected).toBe(0);
  });
  test("the device's check of Hub's preamble", () => {
    for (const c of v.deviceAccepts) expect(acceptSelection(c.device, decodePreamble(fromHex(c.hubHex))!)).toBe(c.version);
    expect(decodePreamble(fromHex(v.wrongMagic))).toBeNull();
  });
  test("a hello of another version fails version 2's frame checks", () => {
    expect(decode(v.notWaiting.hex, LINK2_TCP_PAYLOAD, false).close).toBe(v.notWaiting.close);
  });
});

describe("frames (§4.2, §4.3, §4.7)", () => {
  const v = vector("frames.json");
  test("bytes written by hand", () => {
    expect(toHex(encodePing(7))).toBe("01000000" + "04000000" + "00000000" + "07000000");
    expect(toHex(encodeCredit(5, 65536))).toBe("21000000" + "04000000" + "05000000" + "00000100");
    expect(toHex(encodeReset(0x8000_0009, "refused"))).toBe("22000000" + "04000000" + "09000080" + "02000000");
    expect(toHex(encodeClose("auth", "x"))).toBe("03000000" + "05000000" + "00000000" + "06000000" + "78");
    // REQUEST with APP: the u32 channel id, then the object.
    const app = encodeJsonFrame(LINK2_FRAME.request, 6, { t: "a" }, { channel: 3, body: true });
    expect(toHex(app)).toBe("10060000" + "0d000000" + "06000000" + "03000000" + toHex(new TextEncoder().encode('{"t":"a"}')));
  });
  test("every valid frame decodes and encodes back to its bytes", () => {
    for (const c of v.valid) {
      const { frames, close } = decode(c.hex, c.limit, c.linked);
      expect(close).toBeNull();
      if (c.name.startsWith("an unknown type")) {
        expect(frames.length).toBe(0);
        continue;
      }
      expect(frames.length).toBe(1);
      expect(toHex(encodeFrame(frames[0]))).toBe(c.hex);
    }
  });
  test("a frame of an unknown type is skipped and counted, so a peer takes it as a frame received", () => {
    const decoder = new Link2FrameDecoder();
    decoder.ready(16384);
    const header = new Uint8Array(12);
    header[0] = 0x7e;
    header[4] = 3;
    expect(decoder.push(new Uint8Array([...header, 1, 2, 3]))).toEqual([]);
    expect(decoder.skipped).toBe(1);
    expect(decoder.push(new Uint8Array([...header, 1, 2]))).toEqual([]);
    expect(decoder.skipped).toBe(2);
  });
  test("every refused frame closes with its code", () => {
    for (const c of v.refused) expect(`${c.name}: ${decode(c.hex, c.limit, c.linked).close}`).toBe(`${c.name}: ${c.close}`);
  });
  test("a length over the limit is refused from the header, before a payload byte is buffered", () => {
    const decoder = new Link2FrameDecoder();
    decoder.ready(LINK2_TCP_PAYLOAD);
    const header = new Uint8Array(LINK2_HEADER_BYTES);
    header[0] = LINK2_FRAME.data;
    new DataView(header.buffer).setUint32(4, 0xffff_ffff, true);
    new DataView(header.buffer).setUint32(8, 5, true);
    expect(() => decoder.push(header)).toThrow(LinkCloseError);
    expect(decoder.buffered).toBeLessThanOrEqual(LINK2_HEADER_BYTES);
    expect(() => decoder.push(new Uint8Array(1))).toThrow(LinkCloseError);
  });
  test("bytes split at every position give the same frames", () => {
    const stream = fromHex(v.valid.filter((c: { linked: boolean }) => c.linked).map((c: { hex: string }) => c.hex).join(""));
    const whole = new Link2FrameDecoder();
    whole.ready(LINK2_TCP_PAYLOAD);
    const expected = whole.push(stream);
    for (const size of [1, 2, 5, 11, 12, 13, 64]) {
      const decoder = new Link2FrameDecoder();
      decoder.ready(LINK2_TCP_PAYLOAD);
      const got: Link2Frame[] = [];
      for (let at = 0; at < stream.length; at += size) got.push(...decoder.push(stream.subarray(at, at + size)));
      expect(got.map((f) => toHex(encodeFrame(f)))).toEqual(expected.map((f) => toHex(encodeFrame(f))));
    }
  });
  test("the negotiated limit holds at its edges", () => {
    for (const limit of [LINK2_MIN_PAYLOAD, LINK2_TCP_PAYLOAD, 32_768]) {
      expect(decode(toHex(encodeData(5, new Uint8Array(limit))), limit).close).toBeNull();
      expect(() => encodeData(5, new Uint8Array(limit + 1), false, limit)).toThrow(LinkEncodeError);
    }
    expect(() => new Link2FrameDecoder().ready(512)).toThrow(LinkEncodeError);
  });
  test("an encoder never writes a frame a receiver would refuse", () => {
    expect(() => encodeFrame({ type: LINK2_FRAME.request, flags: LINK2_FLAG.body, id: 5, payload: new Uint8Array(2) })).toThrow(LinkEncodeError);
    expect(() => encodeFrame({ type: LINK2_FRAME.request, flags: 0, id: 0, payload: new Uint8Array(2) })).toThrow(LinkEncodeError);
    expect(() => encodeCredit(5, 0)).toThrow(LinkEncodeError);
    expect(() => encodeData(5, new Uint8Array(0))).toThrow(LinkEncodeError);
  });
  test("PONG echoes the PING's 4 bytes; CLOSE and RESET read back", () => {
    const ping = one(toHex(encodePing(0xdeadbeef)));
    expect(toHex(one(toHex(encodePong(ping))).payload)).toBe("efbeadde");
    expect(parseClose(one(toHex(encodeClose("restart", "starting a .3dsx"))))).toEqual({ code: "restart", number: 9, reason: "starting a .3dsx" });
    const unknown = encodeFrame({ type: LINK2_FRAME.close, flags: 0, id: 0, payload: new Uint8Array([200, 0, 0, 0]) });
    expect(parseClose(one(toHex(unknown))).code).toBe("going_away");
    expect(parseReset(one(toHex(encodeReset(5, "superseded"))))).toEqual({ code: "superseded", number: 5 });
    expect(parseCredit(one(toHex(encodeCredit(5, 4096))))).toBe(4096);
  });
  test("a JSON payload that is not an object reads as null", () => {
    const raw = (text: string) => parseJsonPayload({ type: LINK2_FRAME.request, flags: 0, id: 5, payload: new TextEncoder().encode(text) }).object;
    expect(raw("[1]")).toBeNull();
    expect(raw('"x"')).toBeNull();
    expect(raw("{")).toBeNull();
    expect(raw('﻿{"t":"x"}')).toBeNull();
    expect(raw(' {"b":1, "t":"x"} ')).toEqual({ b: 1, t: "x" });
  });
  test("id ranges", () => {
    for (const c of vector("requests.json").ids) expect(idRange(c.id)).toBe(c.range);
    const device = new IdAllocator("device");
    const hub = new IdAllocator("hub");
    expect([device.take(), device.take(), hub.take(), hub.take()]).toEqual([1, 2, 0x8000_0001, 0x8000_0002]);
  });
});

describe("handshake (§3.4, §3.5)", () => {
  const v = vector("handshake.json");
  test("the proofs are HMAC-SHA256 over the label string with the raw key", () => {
    const hmac = (message: string) => createHmac("sha256", Buffer.from(FIXED.key, "hex")).update(message).digest("hex");
    expect(v.companionMessage).toBe(`pocket-link/2/companion\n${FIXED.deviceNonce}\n${FIXED.hubNonce}\n${FIXED.device}\n${FIXED.hub}`);
    expect(v.consoleMessage).toBe(`pocket-link/2/console\n${FIXED.deviceNonce}\n${FIXED.hubNonce}\n${FIXED.device}\n${FIXED.hub}`);
    expect(v.companionProof).toBe(hmac(v.companionMessage));
    expect(v.consoleProof).toBe(hmac(v.consoleMessage));
    expect(companionProof(FIXED.key, FIXED.deviceNonce, FIXED.hubNonce, FIXED.device, FIXED.hub)).toBe(v.companionProof);
    expect(consoleProof(FIXED.key, FIXED.deviceNonce, FIXED.hubNonce, FIXED.device, FIXED.hub)).toBe(v.consoleProof);
    expect(proofEquals(v.companionProof, v.companionProof)).toBe(true);
    expect(proofEquals(v.companionProof, v.consoleProof)).toBe(false);
    expect(proofEquals(v.companionProof, "zz")).toBe(false);
  });
  test("the transcript, frame by frame", () => {
    const device = new Link2FrameDecoder();
    const hub = new Link2FrameDecoder();
    for (const step of v.transcript) {
      const bytes = fromHex(step.hex);
      if (step.what === "preamble") {
        expect(decodePreamble(bytes)).not.toBeNull();
        continue;
      }
      const frames = (step.from === "device" ? hub : device).push(bytes);
      expect(frames.length).toBe(1);
      expect(frames[0].type).toBe(LINK2_FRAME.handshake);
      expect(frames[0].payload.length).toBeLessThanOrEqual(LINK2_MAX_HANDSHAKE);
      const { object } = parseJsonPayload(frames[0]);
      expect(object).toEqual(step.json);
      expect(toHex(encodeHandshake(step.json))).toBe(step.hex);
      if (step.what === "hello") expect(parseHello(object)).toEqual(step.json);
      if (step.what === "challenge") expect(parseChallenge(object)).toEqual(step.json);
      if (step.what === "auth") expect(parseAuth(object)).toEqual(step.json);
      if (step.what === "ready") expect(parseReady(object)).toEqual(step.json);
    }
  });
  test("a frame behind ready in the same read is read by the rules after ready (§3.3)", () => {
    const ready = fromHex(v.transcript.find((step: { what: string }) => step.what === "ready").hex);
    const request = encodeJsonFrame(LINK2_FRAME.request, 0x8000_0001, { t: "runtime.status" }, { limit: LINK2_TCP_PAYLOAD });
    const credit = encodeCredit(0x8000_0002, 20_000);
    const bytes = new Uint8Array([...ready, ...request, ...credit]);
    for (const size of [bytes.length, 1, 7, 13]) {
      const decoder = new Link2FrameDecoder();
      const got: Link2Frame[] = [];
      for (let at = 0; at < bytes.length; at += size) {
        decoder.write(bytes.subarray(at, at + size));
        for (let frame = decoder.next(); frame !== null; frame = decoder.next()) {
          got.push(frame);
          if (frame.type === LINK2_FRAME.handshake) decoder.ready(LINK2_TCP_PAYLOAD);
        }
      }
      expect(got.map((f) => f.type)).toEqual([LINK2_FRAME.handshake, LINK2_FRAME.request, LINK2_FRAME.credit]);
      expect(decoder.buffered).toBe(0);
    }
    // push() reads a whole chunk by one set of rules: the request behind ready breaks the rules before it.
    expect(decode(toHex(bytes), LINK2_TCP_PAYLOAD, false).close).toBe("protocol");
  });
  test("the payload limit is the smaller offer", () => {
    for (const c of v.limits) expect(payloadLimit(c.hello, c.ready)).toBe(c.limit);
    expect(() => payloadLimit(512, 16_384)).toThrow(LinkEncodeError);
  });
});

describe("refusals (§3.8)", () => {
  const v = vector("handshake-refusals.json");
  test("each refusal reads back", () => {
    for (const c of v.refusals) {
      expect(parseRefused(jsonOfHandshake(c.hex))).toEqual(c.json);
      expect(toHex(encodeHandshake(c.json))).toBe(c.hex);
    }
    expect(parseRefused({ t: "refused", code: "pairing_closed", message: "" })).toBeNull();
  });
  test("a hello that breaks a limit is malformed", () => {
    for (const c of v.malformedHello) {
      const result = parseHello(c.json);
      expect(`${c.name}: ${"refused" in result ? result.refused : "accepted"}`).toBe(`${c.name}: ${c.refused}`);
    }
    expect(parseHello(null)).toEqual({ refused: "malformed", why: "not a hello" });
  });
  test("unknown_device: no key, or another companion id", () => {
    for (const c of v.unknownDevice) {
      const hello = parseHello(c.hello);
      expect("refused" in hello).toBe(false);
      const known = !("refused" in hello) && hello.companion === c.hubId && c.key !== null;
      expect(known ? null : "unknown_device").toBe(c.refused);
    }
  });
  test("bad_proof, and the device's CLOSE auth", () => {
    expect(proofEquals(v.badProof.auth.proof, v.badProof.expected)).toBe(false);
    const expected = companionProof(FIXED.key, FIXED.deviceNonce, FIXED.hubNonce, FIXED.device, FIXED.hub);
    expect(proofEquals(v.deviceCloseAuth.challenge.proof, expected)).toBe(false);
    expect(parseClose(one(v.deviceCloseAuth.close, LINK2_TCP_PAYLOAD, false)).code).toBe("auth");
  });
  test("a ready with maxPayload 512 closes with protocol", () => {
    let code = "";
    try {
      parseReady(v.readyOutOfRange.json);
    } catch (error) {
      code = (error as LinkCloseError).code;
    }
    expect(code).toBe(v.readyOutOfRange.close);
  });
  test("DATA before ready closes with protocol", () => {
    expect(decode(v.dataBeforeReady.hex, LINK2_TCP_PAYLOAD, false).close).toBe(v.dataBeforeReady.close);
  });
});
function jsonOfHandshake(hex: string) {
  return parseJsonPayload(one(hex, LINK2_TCP_PAYLOAD, false)).object;
}

describe("pairing files (§3.1, §3.2, §3.6)", () => {
  const v = vector("pairing-files.json");
  test("the files as Hub writes them", () => {
    expect(v.deviceFile.text).toBe(`${FIXED.device}\n`);
    expect(v.companionFile.text).toBe(`key=${FIXED.key}\nname=Studio Mac\naddress=192.168.1.5\nport=8628\n`);
    expect(parseDeviceFile(v.deviceFile.text)).toBe(v.deviceFile.id);
    expect(parseCompanionFile(v.companionFile.text)).toEqual(v.companionFile.parsed);
    expect(parseLastFile(v.lastFile.text)).toEqual(v.lastFile.parsed);
  });
  test("what the readers accept and refuse", () => {
    for (const c of v.deviceFileReads) expect(`${c.name}: ${parseDeviceFile(c.text)}`).toBe(`${c.name}: ${c.id}`);
    for (const c of v.companionFileReads) expect(parseCompanionFile(c.text)).toEqual(c.parsed);
  });
  test("the device's load of companions/", () => {
    for (const c of v.load) expect(loadCompanions(c.entries)).toEqual({ companions: c.companions, error: c.error });
  });
  test("the device writes .last only when a value changed", () => {
    const loaded = loadCompanions(v.load[0].entries).companions[0];
    expect(lastFileUpdate(loaded, { name: loaded.name, address: loaded.address, port: loaded.port })).toBeNull();
    expect(lastFileUpdate(loaded, { name: loaded.name, address: "10.1.1.1", port: loaded.port })).toBe(`name=Studio Mac\naddress=10.1.1.1\nport=${loaded.port}\n`);
  });
  const replay = (c: { input: Omit<SetupInput, "mintDeviceId" | "mintKey">; minted: { deviceIds: string[]; keys: string[] } }) => {
    let d = 0;
    let k = 0;
    return planSetup({ ...c.input, mintDeviceId: () => c.minted.deviceIds[d++], mintKey: () => c.minted.keys[k++] });
  };
  test("Hub's setup, case by case", () => {
    for (const c of v.setups) {
      const plan = replay(c);
      expect(plan).toEqual(c.plan);
      expect(`${c.name}: ${plan.outcome}`).toBe(`${c.name}: ${c.expect.outcome}`);
      if (c.expect.deviceId !== undefined) expect(plan.deviceId).toBe(c.expect.deviceId);
      if (c.expect.ops !== undefined) expect(plan.ops.length).toBe(c.expect.ops);
      if (c.expect.key !== undefined) expect(plan.key).toBe(c.expect.key);
      if (c.expect.firstOp !== undefined) expect(plan.ops[0].op).toBe(c.expect.firstOp);
    }
  });
  test("a key write goes through .new, and .last goes before the key file is replaced", () => {
    const plan = replay(v.setups[1]);
    expect(plan.ops.map((op: { op: string; path?: string; from?: string; to?: string }) => `${op.op} ${op.path ?? `${op.from} -> ${op.to}`}`)).toEqual([
      `write companions/${FIXED.hub}.new`,
      `readback companions/${FIXED.hub}.new`,
      `delete companions/${FIXED.hub}.last`,
      `delete companions/${FIXED.hub}.txt`,
      `rename companions/${FIXED.hub}.new -> companions/${FIXED.hub}.txt`,
      `readback companions/${FIXED.hub}.txt`,
      "readback device.txt",
    ]);
    // An address change never rewrites the key file.
    const address = replay(v.setups[3]);
    expect(address.ops.some((op: { path?: string; to?: string }) => (op.path ?? op.to) === `companions/${FIXED.hub}.txt`)).toBe(false);
  });
  test("a minted key is the record's key before the first write; a setup whose readback fails is reported as failed", () => {
    const rotate = replay(v.setups[5]);
    expect(rotate.minted).not.toBeNull();
    expect(rotate.key).toBe(rotate.minted);
    const cut = settleSetup(rotate, 5);
    expect(cut.failed).toBe(true);
    expect(cut.failedAt?.op).toBe("readback");
    expect(cut.key).toBe(rotate.minted);
    expect(settleSetup(rotate, rotate.ops.length)).toEqual({ key: rotate.minted, failed: false, failedAt: null });
    const failedRead = replay(v.setups[9]);
    expect(failedRead.outcome).toBe("failed-read");
    expect(settleSetup(failedRead, 0)).toEqual({ key: FIXED.key, failed: true, failedAt: null });
  });
  test("what a cut leaves on the card, by the step it falls in", () => {
    const before = new Map<string, string>(Object.entries(v.powerCut.before));
    const plan = planSetup({
      hubId: FIXED.hub,
      key: v.powerCut.key,
      hub: { name: "Studio Mac", port: 8628 },
      via: { kind: "ftp", localAddress: "192.168.1.5" },
      device: { kind: "file", text: before.get("device.txt")! },
      listing: [{ name: `${FIXED.hub}.txt`, text: before.get(`companions/${FIXED.hub}.txt`)! }],
      companion: { kind: "file", text: before.get(`companions/${FIXED.hub}.txt`)! },
      last: { kind: "file", text: before.get(`companions/${FIXED.hub}.last`)! },
      mintDeviceId: () => "",
      mintKey: () => FIXED.otherKey,
    });
    expect(plan.outcome).toBe("key");
    for (const cut of v.powerCut.cuts) {
      const card = cardAfter(before, plan, cut.completed);
      expect([...card.keys()].sort()).toEqual([...cut.holds].sort());
      const keyFile = card.get(`companions/${FIXED.hub}.txt`);
      const entries = keyFile ? [{ name: `${FIXED.hub}.txt`, text: keyFile }] : [];
      const loaded = loadCompanions(entries).companions;
      if (cut.pairing.startsWith("none")) expect(loaded).toEqual([]);
      else if (cut.pairing === "the new key") expect(loaded[0].key).toBe(FIXED.otherKey);
      else expect(loaded[0].key).toBe(FIXED.key);
    }
  });
});

describe("requests (§5.2, §5.4, §5.5)", () => {
  const v = vector("requests.json");
  test("the transcripts decode, and a REPLY follows every EVENT and DATA of its request", () => {
    for (const name of ["withProgress", "unknownMessage", "malformed", "cancel", "cancelCrossesReply"]) {
      const types = v[name].map((step: { hex: string }) => one(step.hex).type);
      const lastData = Math.max(types.lastIndexOf(LINK2_FRAME.event), types.lastIndexOf(LINK2_FRAME.data));
      const reply = types.indexOf(LINK2_FRAME.reply);
      if (reply >= 0 && name === "withProgress") expect(reply).toBeGreaterThan(lastData);
    }
    expect(jsonOf(v.malformed[0].hex).object).toBeNull();
    expect(jsonOf(v.unknownMessage[1].hex).object).toEqual({ code: "unknown_message", message: "catalog.search" });
  });
  test("an error reply of each generic code", () => {
    for (const c of v.errors) {
      const frame = one(c.hex);
      expect(frame.flags & LINK2_FLAG.error).toBe(LINK2_FLAG.error);
      expect(parseJsonPayload(frame).object?.code).toBe(c.code);
    }
  });
  test("one REPLY ends a request; a second one is ignored", () => {
    const t = clock();
    const requester = new Requester(t.now);
    requester.sent(13);
    expect(requester.frame(13)).toBe("deliver");
    expect(requester.reply(13)).toBe("reply");
    expect(requester.reply(13)).toBe("ignore");
    expect(requester.frame(13)).toBe("discard");
    expect(requester.holds(13)).toBe(false);
  });
  test("30 s without a frame: CANCEL with timeout; progress resets the timer", () => {
    const t = clock();
    const requester = new Requester(t.now);
    requester.sent(1);
    requester.sent(2);
    t.advance(29_000);
    expect(requester.frame(2)).toBe("deliver");
    expect(requester.tick()).toEqual([]);
    t.advance(1000);
    expect(requester.tick()).toEqual([{ action: "cancel", id: 1, error: "timeout" }]);
    t.advance(9999);
    expect(requester.tick()).toEqual([]);
    t.advance(1);
    expect(requester.tick()).toEqual([{ action: "free", id: 1, error: "timeout" }]);
    t.advance(19_000);
    expect(requester.tick()).toEqual([{ action: "cancel", id: 2, error: "timeout" }]);
  });
  test("CANCEL: frames are discarded, the id is freed at the REPLY or 10 s later", () => {
    const t = clock();
    const requester = new Requester(t.now);
    requester.sent(13);
    requester.sent(14);
    expect(requester.cancel(13)).toBe(true);
    expect(requester.cancel(13)).toBe(false);
    expect(requester.frame(13)).toBe("discard");
    expect(requester.reply(13)).toBe("reply");
    expect(requester.cancel(14)).toBe(true);
    t.advance(9999);
    expect(requester.tick()).toEqual([]);
    t.advance(1);
    expect(requester.tick()).toEqual([{ action: "free", id: 14, error: "cancelled" }]);
    expect(requester.size).toBe(0);
  });
  test("channel.open and devtools.open keep their id after the REPLY, with no timer on it", () => {
    const t = clock();
    const requester = new Requester(t.now);
    requester.sent(3, { outlives: true });
    expect(requester.awaiting(3)).toBe(true);
    expect(requester.reply(3)).toBe("reply");
    expect(requester.holds(3)).toBe(true);
    expect(requester.awaiting(3)).toBe(false);
    t.advance(120_000);
    expect(requester.tick()).toEqual([]);
    requester.release(3);
    expect(requester.holds(3)).toBe(false);
  });
  test("a responder answers one over its bound with busy, and replies once per id", () => {
    const responder = new Responder(LINK2_CHANNEL_REQUESTS);
    for (let id = 1; id <= 8; id++) expect(responder.arrived(id)).toBe("accept");
    expect(responder.arrived(9)).toBe("busy");
    expect(responder.reply(1)).toBe(true);
    expect(responder.reply(1)).toBe(false);
    expect(responder.arrived(9)).toBe("accept");
    // CANCEL for a daemon that never answers: the endpoint frees the place at once.
    expect(responder.cancel(2)).toBe(true);
    expect(responder.cancel(2)).toBe(false);
    expect(responder.size).toBe(7);
  });
  test("a stream sender gives up after 30 s without credit; the DevTools stream drops its line and stays", () => {
    const t = clock();
    const event = new StreamSendTimer(t.now);
    const devtools = new StreamSendTimer(t.now, true);
    event.waiting(true);
    devtools.waiting(true);
    t.advance(29_999);
    expect(event.check()).toBe("ok");
    t.advance(1);
    expect(event.check()).toBe("give-up");
    expect(devtools.check()).toBe("drop-line");
    event.waiting(true);
    t.advance(20_000);
    event.credited();
    event.waiting(true);
    t.advance(20_000);
    expect(event.check()).toBe("ok");
  });
});

describe("reading an EVENT (§5.3)", () => {
  test("progress of an applet request is read by its id, whatever its t", () => {
    const holds: Holdings = { ...nothing, channelRequest: (id) => id === 9, ownRequest: (id) => id === 9, inUse: (id) => id === 9 };
    for (const step of vector("channel.json").progressNames) {
      const frame = one(step.hex);
      const t = parseJsonPayload(frame).object?.t as string;
      expect(readEvent("device", frame.id, false, t, holds)).toEqual({ read: "app-progress" });
    }
  });
  test("a late progress event that crossed channel.close is ignored and does not close the link", () => {
    const v = vector("channel.json").lateProgress;
    const frame = one(v.frame.hex);
    const reading = readEvent(v.receiver, frame.id, false, "log", nothing);
    expect(reading.read).toBe(v.reading);
    // The mirror case: a guest's progress on a Hub id after Hub closed the channel.
    expect(readEvent("hub", 0x8000_0005, false, "features", nothing).read).toBe("ignore");
  });
  test("the system event log with id 0 is delivered; with a held or fresh id it is a protocol error", () => {
    expect(readEvent("hub", 0, false, "log", nothing)).toEqual({ read: "system", t: "log", opensStream: false });
    expect(readEvent("hub", 21, false, "log", nothing).read).toBe("close");
    expect(readEvent("device", 0x8000_0021, false, "features", nothing).read).toBe("close");
  });
  test("an id of the sender's range that names nothing held is fresh: it opens a stream in any order", () => {
    // agent.glyphs with an id below one already seen: no mark is kept.
    expect(readEvent("device", 0x8000_0002, false, "agent.glyphs", { ...nothing, inUse: (id) => id === 0x8000_0009 })).toEqual({ read: "system", t: "agent.glyphs", opensStream: true });
    expect(readEvent("device", 0x8000_0002, false, "agent.glyphs", { ...nothing, inUse: () => true }).read).toBe("close");
    expect(readEvent("device", 0, false, "agent.glyphs", nothing).read).toBe("close");
    expect(readEvent("device", 5, false, "agent.glyphs", { ...nothing, inUse: () => true }).read).toBe("close");
  });
  test("0x80000000 is in neither range", () => {
    expect(readEvent("device", 0x8000_0000, false, "log", nothing).read).toBe("close");
  });
  test("an unknown t: ignored, with RESET refused when its id is fresh", () => {
    expect(readEvent("device", 0, false, "agent.hologram", nothing).read).toBe("ignore");
    expect(readEvent("device", 0x8000_0007, false, "agent.hologram", nothing)).toEqual({ read: "reset-refused" });
    expect(readEvent("device", 0x8000_0007, false, null, nothing)).toEqual({ read: "reset-refused" });
  });
  test("runtime.screenshot is told apart by the range of its id", () => {
    const sent: Holdings = { ...nothing, ownRequest: (id) => id === 0x8000_0004, inUse: (id) => id === 0x8000_0004 };
    expect(readEvent("hub", 0x8000_0004, false, "runtime.screenshot", sent)).toEqual({ read: "system", t: "runtime.screenshot", opensStream: false });
    expect(readEvent("hub", 0x8000_0004, false, "runtime.screenshot", nothing).read).toBe("ignore");
    expect(readEvent("hub", 77, false, "runtime.screenshot", nothing)).toEqual({ read: "system", t: "runtime.screenshot", opensStream: true });
  });
  test("channel.close: delivered for an open channel, ignored when it crossed another close", () => {
    expect(readEvent("hub", 3, false, "channel.close", { ...nothing, channel: (id) => id === 3, inUse: (id) => id === 3 }).read).toBe("system");
    expect(readEvent("hub", 3, false, "channel.close", nothing).read).toBe("ignore");
    expect(readEvent("device", 3, false, "channel.close", nothing).read).toBe("ignore");
  });
  test("an APP event: id 0 is standalone, a fresh id of the sender opens a stream", () => {
    expect(readEvent("device", 0, true, "log", nothing)).toEqual({ read: "app", opensStream: false });
    expect(readEvent("device", 0x8000_0011, true, "log.tail", nothing)).toEqual({ read: "app", opensStream: true });
    expect(readEvent("device", 17, true, "log.tail", nothing).read).toBe("close");
  });
});

describe("streams and credit (§5.6)", () => {
  const v = vector("streams.json");
  test("a runtime.push of 100,000 bytes under 64 KiB of credit", () => {
    const sender = new SendCredit();
    const receiver = new ReceiveCredit();
    let moved = 0;
    let ended = false;
    for (const step of v.push.steps.slice(1)) {
      if (step.what === "CREDIT") {
        const bytes = parseCredit(one(step.hex));
        receiver.grant(bytes);
        sender.grant(bytes);
        continue;
      }
      const header = fromHex(step.header);
      const view = new DataView(header.buffer);
      expect(view.getUint32(4, true)).toBe(step.bytes);
      expect(step.bytes).toBeLessThanOrEqual(v.push.limit);
      expect(sender.take(step.bytes)).toBe(step.bytes);
      receiver.received(step.bytes);
      moved += step.bytes;
      ended = (header[1] & LINK2_FLAG.end) !== 0;
    }
    expect(moved).toBe(v.push.bytes);
    expect(ended).toBe(true);
    expect(receiver.granted).toBe(0);
  });
  test("bytes past credit, and a grant over 16 MiB, close with flow", () => {
    const receiver = new ReceiveCredit();
    receiver.grant(v.pastCredit.granted);
    expect(() => receiver.received(v.pastCredit.data)).toThrow(LinkCloseError);
    const sender = new SendCredit();
    sender.grant(v.grantOver16MiB.grants[0]);
    let code = "";
    try {
      sender.grant(v.grantOver16MiB.grants[1]);
    } catch (error) {
      code = (error as LinkCloseError).code;
    }
    expect(code).toBe("flow");
    expect(() => new SendCredit().grant(v.grantAt16MiB.grants[0])).not.toThrow();
  });
  test("credit starts at 0", () => {
    expect(new SendCredit().take(100)).toBe(0);
  });
  test("an unknown event on a fresh id is answered RESET refused", () => {
    const [event, reset] = v.unknownEventWithFreshId;
    const frame = one(event.hex);
    expect(readEvent("device", frame.id, false, parseJsonPayload(frame).object?.t as string, nothing)).toEqual({ read: "reset-refused" });
    expect(parseReset(one(reset.hex)).code).toBe("refused");
    expect(one(reset.hex).id).toBe(frame.id);
  });
});

describe("applet channels (§7)", () => {
  const v = vector("channel.json");
  test("the frames of a channel's life decode, and APP frames carry the channel id", () => {
    for (const name of ["open", "appletRequest", "daemonRequest", "events", "body", "noChannel", "close", "streamEvent"]) {
      for (const step of v[name]) {
        const frame = one(step.hex);
        const payload = parseJsonPayload(frame);
        if ((frame.flags & LINK2_FLAG.app) !== 0) expect([3, 29]).toContain(payload.channel ?? -1);
        else expect(payload.channel).toBeUndefined();
      }
    }
    expect(jsonOf(v.open[1].hex).object).toEqual({ generation: 7 });
    expect(jsonOf(v.close[2].hex).object).toEqual({ generation: 8 });
    // The first unit grant follows the REPLY of channel.open.
    expect(one(v.open[1].hex).type).toBe(LINK2_FRAME.reply);
    expect(one(v.open[2].hex).type).toBe(LINK2_FRAME.credit);
    expect(parseCredit(one(v.open[3].hex))).toBe(LINK2_APP_EVENT_WINDOW);
  });
  test("LINK_APP_MSG = min(8,192, payload limit − 4), refused by the sender's own endpoint", () => {
    for (const c of v.sizes) expect(appMessageLimit(c.payloadLimit)).toBe(c.appMessage);
    for (const c of v.tooLarge) {
      const object = { t: "x", pad: "" };
      object.pad = "p".repeat(c.objectBytes - jsonBytes(object));
      expect(jsonBytes(object)).toBe(c.objectBytes);
      const attempt = () => encodeJsonFrame(LINK2_FRAME.request, 5, object, { channel: 3, limit: c.payloadLimit });
      if (c.refusedBy === "sender") expect(attempt).toThrow(/too_large/);
      else expect(attempt().length).toBe(LINK2_HEADER_BYTES + 4 + c.objectBytes);
    }
  });
  test("the response of 18,244 bytes: the head event, DATA under the 16 KiB window, a second grant after the guest's read, END, then the REPLY", () => {
    const steps = v.response.steps;
    const whats = steps.map((s: { what: string }) => s.what);
    const head = whats.findIndex((w: string) => w.includes("head step"));
    const firstData = whats.findIndex((w: string) => w.startsWith("DATA"));
    const reply = whats.findIndex((w: string) => w.startsWith("REPLY"));
    expect(head).toBeLessThan(firstData);
    expect(reply).toBe(steps.length - 1);
    const data = steps.filter((s: { bytes?: number }) => s.bytes !== undefined).map((s: { bytes: number }) => s.bytes);
    expect(data).toEqual([16_384, 1860]);
    expect(steps.filter((s: { what: string }) => s.what.startsWith("CREDIT")).length).toBe(2);
    // The head event carries no APP flag and the request's id.
    const headFrame = one(steps[head].hex);
    expect(headFrame.flags).toBe(0);
    expect(headFrame.id).toBe(9);
  });

  /** Runs response streams to completion. Each frame: the guest reads, the
   *  device grants against pending reads, the daemon sends within credit,
   *  the host hands over at most 16 KiB of stream bytes in turn. */
  function run(streams: { total: number; reads: boolean; handleAt: "head" | "reply" }[], frames = 400) {
    const windows = streams.map(() => new AppletStreamWindow());
    const credits = streams.map(() => new SendCredit());
    const sent = streams.map(() => 0);
    const taken = streams.map(() => 0);
    const doneAt: (number | null)[] = streams.map(() => null);
    let peak = 0;
    for (let frame = 0; frame < frames; frame++) {
      streams.forEach((s, i) => {
        // The guest holds the stream from the head event on; a handle given
        // only at the REPLY never arrives, since the REPLY waits behind the bytes.
        const hasHandle = s.handleAt === "head" || sent[i] === s.total;
        if (s.reads && hasHandle) windows[i].read(LINK2_APP_STREAM_WINDOW);
        const grant = windows[i].grant();
        if (grant > 0) credits[i].grant(grant);
        const n = credits[i].take(Math.min(LINK2_TCP_PAYLOAD, s.total - sent[i]));
        sent[i] += n;
        windows[i].received(n);
        expect(windows[i].occupied).toBeLessThanOrEqual(LINK2_APP_STREAM_WINDOW);
      });
      peak = Math.max(peak, windows.reduce((sum, w) => sum + w.occupied, 0));
      shareFrameBytes(windows, frame, LINK2_APP_FRAME_STREAM).forEach((n, i) => {
        taken[i] += n;
        if (taken[i] === streams[i].total && doneAt[i] === null && streams[i].total > 0) doneAt[i] = frame;
      });
    }
    return { sent, taken, doneAt, peak, held: windows.map((w) => w.occupied) };
  }

  test("a response longer than the window completes with the head step, and never without it", () => {
    for (const total of [16_384, 18_244, 518_400]) {
      expect(run([{ total, reads: true, handleAt: "head" }]).taken[0]).toBe(total);
    }
    expect(run([{ total: 16_384, reads: true, handleAt: "reply" }]).sent[0]).toBe(0);
    const stuck = run([{ total: 18_244, reads: true, handleAt: "reply" }]);
    expect(stuck.sent[0]).toBe(0);
    expect(stuck.taken[0]).toBe(0);
  });
  test("the endpoint next to the responder refuses bytes before a progress event", () => {
    const gate = new ResponseGate();
    expect(gate.mayWrite).toBe(false);
    expect(() => gate.write()).toThrow(/before a progress event/);
    gate.progress();
    expect(() => gate.write()).not.toThrow();
    gate.reply();
    expect(() => gate.write()).toThrow(/after the reply/);
  });
  test("a read left pending on an idle stream holds its own window and none of another's", () => {
    // Stream 0 is a log tail with nothing to send; its read stays pending.
    const result = run([
      { total: 0, reads: true, handleAt: "head" },
      { total: 18_244, reads: true, handleAt: "head" },
    ]);
    expect(result.taken[1]).toBe(18_244);
    expect(result.held[0]).toBe(LINK2_APP_STREAM_WINDOW);
    const three = run([
      { total: 0, reads: true, handleAt: "head" },
      { total: 0, reads: true, handleAt: "head" },
      { total: 0, reads: true, handleAt: "head" },
      { total: 518_400, reads: true, handleAt: "head" },
    ]);
    expect(three.taken[3]).toBe(518_400);
    expect(three.peak).toBeLessThanOrEqual(4 * LINK2_APP_STREAM_WINDOW);
  });
  test("a stream nobody reads is granted nothing, and the one beside it completes", () => {
    const result = run([
      { total: 18_244, reads: false, handleAt: "head" },
      { total: 18_244, reads: true, handleAt: "head" },
    ]);
    expect(result.sent[0]).toBe(0);
    expect(result.held[0]).toBe(0);
    expect(result.taken[1]).toBe(18_244);
  });
  test("four streams read together: at most four windows held, the first served changes each frame", () => {
    const result = run(Array.from({ length: 4 }, () => ({ total: 262_144, reads: true, handleAt: "head" as const })));
    expect(result.taken).toEqual([262_144, 262_144, 262_144, 262_144]);
    expect(result.peak).toBeLessThanOrEqual(4 * LINK2_APP_STREAM_WINDOW);
    const done = result.doneAt as number[];
    expect(Math.max(...done) - Math.min(...done)).toBeLessThanOrEqual(4);
  });
  test("DATA past an applet stream's credit closes with flow", () => {
    const window = new AppletStreamWindow();
    // No read pending: nothing is granted.
    expect(window.grant()).toBe(0);
    // A read of any size opens the whole window (the next reads' bytes are in flight meanwhile).
    window.read(100);
    expect(window.grant()).toBe(LINK2_APP_STREAM_WINDOW);
    expect(window.grant()).toBe(0);
    expect(() => window.received(LINK2_APP_STREAM_WINDOW + 1)).toThrow(LinkCloseError);
  });

  test("the event window: units of 512 bytes, 48 from the device, 256 from Hub", () => {
    const w = v.eventWindow;
    for (const c of w.costs) expect(eventUnits(c.jsonBytes)).toBe(c.units);
    const receiver = new EventReceiver();
    const sender = new EventSender();
    sender.grant(receiver.open());
    expect(sender.available).toBe(w.deviceGrants);
    expect(sender.send(600)).toBe(true);
    expect(receiver.arrived(600)).toBe(2);
    expect(receiver.granted).toBe(w.afterOneOf600);
    expect(new EventReceiver(256).open()).toBe(w.hubGrants);
  });
  test("a sender without units keeps the event; nothing is dropped and nothing closes", () => {
    const receiver = new EventReceiver();
    const sender = new EventSender();
    sender.grant(receiver.open());
    const queue: number[] = [];
    let waitingAtHub = 0;
    // 200 events a second of 200 bytes while the guest is paused for 2 s.
    for (let i = 0; i < 400; i++) {
      if (sender.send(200)) {
        const cost = receiver.arrived(200);
        expect(cost).not.toBe("overflow");
        queue.push(cost as number);
      } else waitingAtHub++;
    }
    expect(queue.length).toBe(48);
    expect(waitingAtHub).toBe(352);
    // The guest wakes and takes 4 a frame: the units come back in one CREDIT per turn.
    for (const cost of queue.splice(0, 4)) receiver.left(cost);
    const regrant = receiver.regrant();
    expect(regrant).toBe(4);
    sender.grant(regrant);
    expect(sender.available).toBe(4);
    expect(receiver.regrant()).toBe(0);
  });
  test("a stall of 100 ms at 200 events a second stays under the window", () => {
    const receiver = new EventReceiver();
    const sender = new EventSender();
    sender.grant(receiver.open());
    const queue: number[] = [];
    for (let i = 0; i < 20; i++) {
      expect(sender.send(200)).toBe(true);
      queue.push(receiver.arrived(200) as number);
    }
    expect(queue.reduce((a, b) => a + b, 0)).toBeLessThan(LINK2_APP_EVENT_WINDOW);
  });
  test("100 requests cancelled with their head event on the wire leave 48 units", () => {
    const receiver = new EventReceiver();
    const sender = new EventSender();
    sender.grant(receiver.open());
    for (let i = 0; i < 100; i++) {
      // The daemon's head event was sent; the device cancelled and discards it.
      expect(sender.send(80)).toBe(true);
      const cost = receiver.arrived(80);
      expect(cost).toBe(1);
      receiver.left(cost as number);
      sender.grant(receiver.regrant());
    }
    expect(sender.available).toBe(LINK2_APP_EVENT_WINDOW);
    expect(receiver.granted).toBe(LINK2_APP_EVENT_WINDOW);
  });
  test("units returned only when the guest takes an event would leave the daemon without any", () => {
    const receiver = new EventReceiver();
    const sender = new EventSender();
    sender.grant(receiver.open());
    let sent = 0;
    for (let i = 0; i < 100; i++) {
      if (!sender.send(80)) break;
      receiver.arrived(80);
      sent++;
    }
    expect(sent).toBe(48);
    expect(sender.available).toBe(0);
  });
  test("an event past the granted units is overflow: channel.close, not the link", () => {
    const receiver = new EventReceiver(1);
    receiver.open();
    expect(receiver.arrived(v.eventWindow.overflow.eventJsonBytes)).toBe("overflow");
    const close = one(v.eventWindow.overflow.answer);
    expect(close.type).toBe(LINK2_FRAME.event);
    expect(close.id).toBe(3);
    expect(parseJsonPayload(close).object).toEqual({ t: "channel.close", reason: "overflow" });
  });
  test("channel.open retries after busy: 2 s doubling to 60 s", () => {
    const busy = v.openRefusals.find((c: { code: string }) => c.code === "busy");
    let wait = 2000;
    const waits: number[] = [];
    for (let i = 0; i < busy.retryMs.length; i++) {
      waits.push(wait);
      wait = Math.min(wait * 2, 60_000);
    }
    expect(waits).toEqual(busy.retryMs);
  });
});

describe("runtime.apps paging (§6.2)", () => {
  const v = vector("messages.json").runtimeApps;
  const row = (i: number): Link2InstalledApp => ({ id: `dev.example.a${i}`, output: `a${i}`, version: "1.0.0", hash: i.toString(16).padStart(16, "0") });
  test("a report of ordinary size is one page on TCP; one at every limit takes two", () => {
    expect(v.ordinary.tcp.length).toBe(1);
    expect(v.atLimits.tcp.map((p: { rows: number }) => p.rows)).toEqual([54, 10]);
    expect(v.atLimits.floor.length).toBe(22);
    for (const page of [...v.ordinary.tcp, ...v.atLimits.tcp]) expect(page.bytes).toBeLessThanOrEqual(LINK2_TCP_PAYLOAD);
    for (const page of v.atLimits.floor) expect(page.bytes).toBeLessThanOrEqual(LINK2_MIN_PAYLOAD);
    expect(v.atLimits.rowBytes).toBeLessThan(300);
  });
  test("pages are whole rows in order, and at counts the rows before", () => {
    const rows = Array.from({ length: 64 }, (_, i) => row(i));
    const pages = pageRuntimeApps(rows, 7, LINK2_MIN_PAYLOAD);
    let at = 0;
    for (const page of pages) {
      expect(page.set).toBe(7);
      expect(page.at).toBe(at);
      expect(page.apps.length).toBeGreaterThan(0);
      expect(jsonBytes(page)).toBeLessThanOrEqual(LINK2_MIN_PAYLOAD);
      at += page.apps.length;
    }
    expect(pages.flatMap((p) => p.apps)).toEqual(rows);
    expect(pages[pages.length - 1].more).toBe(false);
    expect(pages.slice(0, -1).every((p) => p.more)).toBe(true);
    expect(pageRuntimeApps([], 1, LINK2_MIN_PAYLOAD)).toEqual([{ t: "runtime.apps", set: 1, at: 0, apps: [], more: false }]);
    expect(() => pageRuntimeApps(Array.from({ length: 65 }, (_, i) => row(i)), 1, LINK2_TCP_PAYLOAD)).toThrow(RangeError);
  });
  test("a report of more than 64 rows closes the link with protocol", () => {
    const assembler = new RuntimeAppsAssembler();
    assembler.page({ t: "runtime.apps", set: 1, at: 0, apps: Array.from({ length: 40 }, (_, i) => row(i)), more: true });
    expect(() => assembler.page({ t: "runtime.apps", set: 1, at: 40, apps: Array.from({ length: 25 }, (_, i) => row(40 + i)), more: false })).toThrow(LinkCloseError);
  });
  test("Hub's assembly, case by case", () => {
    for (const c of v.assembler) {
      const assembler = new RuntimeAppsAssembler();
      const got = c.pages.map((p: { set: number; at: number; rows: number; more: boolean }) => {
        const apps = Array.from({ length: p.rows }, (_, i) => row(p.at + i));
        try {
          const complete = assembler.page({ t: "runtime.apps", set: p.set, at: p.at, apps, more: p.more });
          return complete === null ? null : complete.length;
        } catch (error) {
          return (error as LinkCloseError).code;
        }
      });
      expect(`${c.name}: ${JSON.stringify(got)}`).toBe(`${c.name}: ${JSON.stringify(c.complete)}`);
    }
  });
  test("a report restarted under the next set replaces the partial one; Hub keeps the last complete set meanwhile", () => {
    const assembler = new RuntimeAppsAssembler();
    const rows = (from: number, n: number) => Array.from({ length: n }, (_, i) => row(from + i));
    expect(assembler.page({ t: "runtime.apps", set: 1, at: 0, apps: rows(0, 3), more: false })?.length).toBe(3);
    expect(assembler.page({ t: "runtime.apps", set: 2, at: 0, apps: rows(0, 40), more: true })).toBeNull();
    expect(assembler.apps.length).toBe(3);
    expect(assembler.page({ t: "runtime.apps", set: 3, at: 0, apps: rows(0, 41), more: true })).toBeNull();
    expect(assembler.page({ t: "runtime.apps", set: 2, at: 40, apps: rows(40, 2), more: false })).toBeNull();
    expect(assembler.page({ t: "runtime.apps", set: 3, at: 41, apps: rows(41, 1), more: false })?.length).toBe(42);
  });
});

describe("catalog paging (§6.4)", () => {
  const v = vector("messages.json").catalog;
  const app = (id: string, more: Partial<{ title: string; version: string; summary: string; output: string }> = {}) => ({ id, title: "T", version: "1", summary: "", output: "o", hash: "0".repeat(16), bytes: 1, ...more });
  test("rows are ordered by id in byte order, and the first 64 are served", () => {
    expect(v.served).toBe(64);
    expect(v.firstServed).toBe("dev.example.app-00");
    expect(v.lastServed).toBe("dev.example.app-63");
    expect(["b", "a", "B", "é", "aa"].sort(compareIdBytes)).toEqual(["B", "a", "aa", "b", "é"]);
  });
  test("a row at every limit fits the 1 KiB floor beside the reply's fields", () => {
    expect(v.rowAtLimits.bytes).toBeLessThanOrEqual(520);
    expect(v.rowAtLimits.pageBytes).toBeLessThanOrEqual(LINK2_MIN_PAYLOAD);
  });
  test("title and summary are cut on a code point; an app whose id, output or version is over its limit is left out", () => {
    const rows = catalogRows([
      app("a", { title: "t".repeat(63) + "中", summary: "s".repeat(200) }),
      app("i".repeat(129)),
      app("b", { output: "o".repeat(65) }),
      app("c", { version: "v".repeat(33) }),
      app("a", { title: "second folder" }),
    ]);
    expect(rows.map((r) => r.id)).toEqual(["a"]);
    expect(rows[0].title).toBe("t".repeat(63));
    expect(rows[0].summary.length).toBe(120);
  });
  test("a fetch at the floor completes from the snapshot while the offer changes", () => {
    expect(v.fetch[0].rows).toBe(64);
    expect(v.fetch[0].firstId).toBe("dev.example.app-00");
    expect(v.fetch[0].lastId).toBe("dev.example.app-63");
    const t = clock();
    let offer = Array.from({ length: 10 }, (_, i) => app(`app-${i}`, { summary: "s".repeat(100), title: "t".repeat(60) }));
    const pager = new CatalogPager(() => offer, t.now);
    const first = pager.request({}, LINK2_MIN_PAYLOAD);
    if (!("reply" in first)) throw new Error("no first page");
    expect(first.reply.more).toBe(true);
    offer = [app("zzz")];
    pager.changed();
    const ids = first.reply.apps.map((r) => r.id);
    let page = first.reply;
    while (page.more) {
      t.advance(29_000);
      const next = pager.request({ after: page.apps[page.apps.length - 1].id, rev: page.rev }, LINK2_MIN_PAYLOAD);
      if (!("reply" in next)) throw new Error(`a page answered ${next.error}`);
      expect(jsonBytes(next.reply)).toBeLessThanOrEqual(LINK2_MIN_PAYLOAD);
      page = next.reply;
      ids.push(...page.apps.map((r) => r.id));
    }
    expect(ids).toEqual(Array.from({ length: 10 }, (_, i) => `app-${i}`));
    // The next first page serves the new offer under the new revision.
    const fresh = pager.request({}, LINK2_MIN_PAYLOAD);
    expect("reply" in fresh && fresh.reply.apps.map((r) => r.id)).toEqual(["zzz"]);
    expect("reply" in fresh ? fresh.reply.rev : -1).toBe(first.reply.rev + 1);
  });
  test("a page request 31 s after the last one, or for a replaced snapshot, is answered changed", () => {
    expect(v.after31s).toEqual({ error: "changed" });
    expect(v.unknownAfter).toEqual({ error: "malformed" });
    const t = clock();
    const offer = Array.from({ length: 10 }, (_, i) => app(`app-${i}`, { summary: "s".repeat(100) }));
    const pager = new CatalogPager(() => offer, t.now);
    const a = pager.request({}, LINK2_MIN_PAYLOAD);
    pager.changed();
    pager.request({}, LINK2_MIN_PAYLOAD);
    if (!("reply" in a)) throw new Error("no page");
    expect(pager.request({ after: a.reply.apps[0].id, rev: a.reply.rev }, LINK2_MIN_PAYLOAD)).toEqual({ error: "changed" });
    expect(pager.request({ after: "app-0" }, LINK2_MIN_PAYLOAD)).toEqual({ error: "malformed" });
    expect(pager.request({ rev: 1 }, LINK2_MIN_PAYLOAD)).toEqual({ error: "malformed" });
  });
  test("a device runs one fetch at a time; changed restarts it; a second one starts after it", () => {
    const fetch = new CatalogFetch();
    expect(fetch.start()).toEqual({ send: { t: "catalog" } });
    expect(fetch.start()).toBeNull();
    expect(fetch.reply({ apps: [app("a")], rev: 4, more: true })).toEqual({ send: { t: "catalog", after: "a", rev: 4 } });
    expect(fetch.error("changed")).toEqual({ send: { t: "catalog" } });
    expect(fetch.reply({ apps: [app("a"), app("b")], rev: 5, more: false })).toEqual({ done: [app("a"), app("b")] });
    expect(fetch.running).toBe(false);
    expect(fetch.next()).toEqual({ send: { t: "catalog" } });
    expect(fetch.error("busy")).toEqual({ failed: "busy" });
    expect(fetch.next()).toBeNull();
  });
});

describe("message sizes (§3.4, §6.2, §6.5)", () => {
  const v = vector("messages.json");
  test("hello and ready at every limit fit the 1,024 bytes of a handshake", () => {
    expect(v.handshake.hello.bytes).toBeLessThanOrEqual(LINK2_MAX_HANDSHAKE);
    expect(v.handshake.ready.bytes).toBeLessThanOrEqual(LINK2_MAX_HANDSHAKE);
    expect(parseHello(v.handshake.hello.json)).toEqual(v.handshake.hello.json);
    expect(parseReady(v.handshake.ready.json)).toEqual(v.handshake.ready.json);
    expect(() => encodeHandshake(v.handshake.hello.json)).not.toThrow();
  });
  test("net.http and net.head at their encoded limits fit 12,288 and 16,384", () => {
    expect(v.http.request.urlBytes).toBe(2048);
    expect(v.http.request.headersBytes).toBe(8192);
    expect(Object.keys(v.http.request.json.headers).length).toBe(32);
    for (const limit of [LINK2_HTTP_MIN_PAYLOAD, LINK2_TCP_PAYLOAD]) {
      expect(v.http.request.bytes).toBeLessThanOrEqual(limit);
      expect(v.http.head.bytes).toBeLessThanOrEqual(limit);
    }
    expect(v.http.request.bytes).toBeGreaterThan(LINK2_MIN_PAYLOAD);
    // A limit counts the encoded form: one newline costs two bytes.
    expect(v.http.escaped.encodedBytes).toBe(v.http.escaped.text.length + 1);
  });
  test("a log event at the 1 KiB floor with frame and dropped at 2^32 − 1", () => {
    expect(v.log.json.text.length).toBe(LINK2_MIN_PAYLOAD - 96);
    expect(v.log.bytes).toBeLessThanOrEqual(LINK2_MIN_PAYLOAD);
  });
});

describe("features (§6.1)", () => {
  const v = vector("features.json");
  test("lists within the limits read back", () => {
    for (const c of v.valid) {
      const object = jsonOf(c.hex).object;
      expect(object?.t).toBe("features");
      expect(parseFeatures(object?.features)).toEqual(c.list);
    }
  });
  test("a list over the limits, or none, closes with protocol", () => {
    for (const c of v.protocol) expect(`${c.name}: ${parseFeatures(c.json.features)}`).toBe(`${c.name}: null`);
  });
  test("a group is in use only when both lists name it", () => {
    for (const c of v.inUse) expect(c.device.filter((f: string) => c.hub.includes(f))).toEqual(c.inUse);
  });
});

describe("keepalive (§4.6)", () => {
  const v = vector("keepalive.json");
  test("PING and PONG", () => {
    const ping = one(v.ping);
    expect(toHex(encodePong(ping))).toBe(v.pong);
    expect(v.pingMs).toBe(LINK2_PING_MS);
    expect(v.silenceMs).toBe(LINK2_SILENCE_MS);
  });
  test("the timelines", () => {
    for (const c of v.timelines) {
      const t = clock();
      const keepalive = new Keepalive(t.now, LINK2_PING_MS, LINK2_SILENCE_MS);
      let silenceAt: number | null = null;
      let pings = 0;
      for (let ms = 100; ms <= c.until && silenceAt === null; ms += 100) {
        t.set(ms);
        if (c.received.includes(ms)) keepalive.received();
        const tick = keepalive.tick();
        if (tick === "silence") silenceAt = ms;
        if (tick === "ping") pings++;
      }
      expect(`${c.name}: ${silenceAt}`).toBe(`${c.name}: ${c.silenceAt}`);
      if (c.silenceAt === null) expect(pings).toBe(Math.floor(c.until / LINK2_PING_MS));
    }
  });
});
